// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.persona.survivalimport timber.log.Timberimport com.roshan.persona.persona.core.PersonaProfileimport com.roshan.persona.persona.masking.DynamicFillerEngineimport com.roshan.persona.persona.masking.FillerCategoryimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContextimport java.util.concurrent.atomic.AtomicIntegerimport java.util.concurrent.atomic.AtomicLong/** * NOUS — Token Survival Manager (Module 15 v3.0 — Step 15.5 FINAL). * * Implements **Strategy B: Token Survival ("The Nap")** from strategy §5. * * When the LLM context window hits 85% capacity, NOUS performs a graceful * **"Context Compression"** masked as fatigue — NOUS takes a "nap" to * reorganize its thoughts, then returns refreshed. * * ## The "Nap" Flow (per strategy §5 Strategy B) * * ``` * 1. Trigger: ContextWindowManager detects usage > 85% *    ↓ * 2. NOUS speaks (via DynamicFillerEngine CONTEXT_COMPRESSION filler): *    Atlas: "A moment, sir — organizing my thoughts." *    Nova: "Hold on, my mind's a bit full!" *    Onyx: "Reorganizing." *    ↓ * 3. Background LLM runs a hidden prompt: *    "Summarize the current conversation in 100 tokens." *    ↓ * 4. Raw conversation context is WIPED. *    ↓ * 5. The 100-token summary is injected as the new context baseline. *    ↓ * 6. NOUS returns (via TTS): *    Atlas: "I'm seeing you, sir. Now then, we were discussing..." *    Nova: "Okay I'm back! So we were talking about..." *    ↓ * 7. Conversation continues with compact context — no information loss *    (the summary preserves key facts), but token usage drops to ~10%. * ``` * * ## Why mask it as fatigue? * * Exposing "I hit my context limit" to the user is a technical limitation. * Masking it as "my mind is full, let me reorganize" is a **character trait** — * NOUS feels more human. The user never knows about token limits; they just * see NOUS briefly pausing to "think." * * ## Cooldown * * Compression has a cooldown (default 30 seconds) — prevents compressing * every turn if the user is in a long conversation. After a compression, * the context drops to ~10%, so it takes many turns to fill up again. * * ## Token counting * * The manager tracks approximate token count via [TokenCounter]. Real impl * uses the LLM provider's tokenizer; tests inject a fake that counts * characters / 4 (rough approximation). * * @see <a href="docs/strategy/module-15-digital-soul-strategy.md">§5 Token Survival & Latency Masking — Strategy B</a> */class TokenSurvivalManager(    private val summarizer: ContextSummarizer,    private val fillerEngine: DynamicFillerEngine,    private val tokenCounter: TokenCounter,    private val config: SurvivalConfig = SurvivalConfig(),    private val dispatcher: CoroutineDispatcher,) {    /** Current approximate token count in the context window. */    private val currentTokens = AtomicInteger(0)    /** Maximum tokens the context window can hold. */    private val maxTokens: Int get() = config.maxContextTokens    /** Timestamp of the last compression (for cooldown). */    private val lastCompressionMs = AtomicLong(0)    /** Total number of compressions performed (for diagnostics). */    private val compressionCount = AtomicInteger(0)    /**     * Add text to the context window and update the token count.     *     * Called by Brain after each conversation turn (user input + NOUS response).     *     * @param text the text to add (user utterance + NOUS response).     */    fun addContext(text: String) {        val tokens = tokenCounter.count(text)        currentTokens.addAndGet(tokens)        Timber.tag(TAG).d("Added $tokens tokens (total: ${currentTokens.get()}/$maxTokens).")    }    /**     * Get the current context window usage as a percentage (0-100).     */    fun getUsagePercent(): Int {        if (maxTokens == 0) return 0        return ((currentTokens.get().toFloat() / maxTokens) * 100).toInt().coerceIn(0, 100)    }    /**     * Check if context compression ("nap") should be triggered.     *     * Returns true if:     *  - Current usage >= [SurvivalConfig.compressionThresholdPercent] (85%).     *  - The cooldown period has elapsed since the last compression.     *     * @param nowMs current epoch time (injectable for testing).     * @return true if the "nap" should be triggered.     */    fun shouldCompress(nowMs: Long = System.currentTimeMillis()): Boolean {        if (getUsagePercent() < config.compressionThresholdPercent) return false        val elapsed = nowMs - lastCompressionMs.get()        if (elapsed < config.compressionCooldownMs) return false        return true    }    /**     * Perform context compression ("nap").     *     * This is the main entry point — called by Brain when [shouldCompress]     * returns true.     *     * ## Steps     *  1. Get the "nap" filler text (persona-specific).     *  2. Call the LLM to summarize the raw context into ~100 tokens.     *  3. Wipe the raw context.     *  4. Inject the summary as the new context baseline.     *  5. Update token count + compression metadata.     *     * @param rawContext the full conversation text to summarize.     * @param persona the active persona (for filler text).     * @return a [CompressionResult] with the summary + filler text, or null     *         if summarization failed.     */    suspend fun compress(        rawContext: String,        persona: PersonaProfile,    ): CompressionResult? = withContext(dispatcher) {        Timber.tag(TAG).i("Starting context compression (nap) for ${persona.id}.")        // 1. Get the "nap" filler — NOUS tells the user it's reorganizing.        val napFiller = fillerEngine.getFiller(persona, FillerCategory.CONTEXT_COMPRESSION)            ?: "Give me a second."  // fallback for SILENT personas        // 2. Call the LLM to summarize.        val summary = try {            summarizer.summarize(rawContext, config.summaryMaxTokens)        } catch (t: Throwable) {            Timber.tag(TAG).e("Summarization failed — aborting compression.", t)            return@withContext null        }        if (summary.isNullOrBlank()) {            Timber.tag(TAG).w("Summarization returned empty — aborting compression.")            return@withContext null        }        // 3. Wipe raw context + inject summary.        val summaryTokens = tokenCounter.count(summary)        currentTokens.set(summaryTokens)        lastCompressionMs.set(System.currentTimeMillis())        compressionCount.incrementAndGet()        Timber.tag(TAG).i("Compression complete: ${rawContext.length} chars → ${summary.length} chars " +            "(${summaryTokens} tokens). Total compressions: ${compressionCount.get()}.")        // 4. Return the result — caller plays the filler + then the "I'm back" message.        val returnMessage = buildReturnMessage(persona)        CompressionResult(            napFiller = napFiller,            summary = summary,            returnMessage = returnMessage,            tokensBefore = currentTokens.get() + tokenCounter.count(rawContext),  // approximate            tokensAfter = summaryTokens,            compressionCount = compressionCount.get(),        )    }    /**     * Build the "I'm back" return message for [persona].     *     * After the nap + summary injection, NOUS tells the user it's ready to     * continue. Each persona has a distinct return style.     */    private fun buildReturnMessage(persona: PersonaProfile): String {        return when (persona.id) {            "atlas" -> "I'm seeing you, sir. Now then, where were we?"            "nova" -> "Okay, I'm back! So we were talking about..."            "onyx" -> "Resumed. Continue."            "sage" -> "I'm here. Let's pick up where we left off."            "echo" -> "Alright, I'm back! So yeah, we were on..."            "vanguard" -> "Reorganized. Proceed."            "aria" -> "I'm back! Let's keep going!"            "wraith" -> "Back."            "zenith" -> "I'm here. Let's continue."            else -> "I'm back. Let's continue."        }    }    /** Get the current token count. */    fun getCurrentTokens(): Int = currentTokens.get()    /** Get the total number of compressions performed. */    fun getCompressionCount(): Int = compressionCount.get()    /** Reset all state (for tests + Settings → Reset). */    fun reset() {        currentTokens.set(0)        lastCompressionMs.set(0)        compressionCount.set(0)    }    private companion object {        private const val TAG = "TokenSurvivalManager"    }}// ──────────────────────────────────────────────────────────────────────────/** * Result of a context compression ("nap"). * * @param napFiller       the filler NOUS speaks BEFORE the nap ("organizing my thoughts"). * @param summary         the 100-token summary (injected as new context baseline). * @param returnMessage   the message NOUS speaks AFTER the nap ("I'm back"). * @param tokensBefore    approximate token count before compression. * @param tokensAfter     token count after compression (summary only). * @param compressionCount total compressions performed so far. */data class CompressionResult(    val napFiller: String,    val summary: String,    val returnMessage: String,    val tokensBefore: Int,    val tokensAfter: Int,    val compressionCount: Int,) {    /** How many tokens were saved by compression. */    val tokensSaved: Int get() = (tokensBefore - tokensAfter).coerceAtLeast(0)    /** Compression ratio (e.g., 0.1 = summary is 10% of original). */    val compressionRatio: Float get() =        if (tokensBefore > 0) tokensAfter.toFloat() / tokensBefore else 0f}// ──────────────────────────────────────────────────────────────────────────/** * Summarizes conversation context into a compact summary. * * Real implementation calls the LLM (Module 4) with a hidden prompt: * "Summarize the following conversation in [maxTokens] tokens. Preserve * key facts, user preferences, and the current topic." * * Tests inject a fake that returns a canned summary. */fun interface ContextSummarizer {    /**     * Summarize [rawContext] into at most [maxTokens] tokens.     *     * @return the summary text, or null if summarization failed.     */    suspend fun summarize(rawContext: String, maxTokens: Int): String?}// ──────────────────────────────────────────────────────────────────────────/** * Counts tokens in text. * * Real implementation uses the LLM provider's tokenizer (Module 4). * For v1, we use a rough approximation: tokens ≈ characters / 4. * * Tests inject a fake for deterministic counts. */fun interface TokenCounter {    /** Count the approximate number of tokens in [text]. */    fun count(text: String): Int}/** * Default [TokenCounter] — rough approximation (chars / 4). * * This is the industry-standard heuristic for English text. For CJK * languages, the ratio is closer to 1:1, but v1 uses the English * approximation — good enough for threshold detection. */class ApproximateTokenCounter : TokenCounter {    override fun count(text: String): Int {        if (text.isEmpty()) return 0        return (text.length / 4).coerceAtLeast(1)    }}// ──────────────────────────────────────────────────────────────────────────/** * Configuration for the Token Survival Manager. * * @param maxContextTokens           maximum tokens the LLM context window holds. * @param compressionThresholdPercent usage % that triggers compression (default 85%). * @param compressionCooldownMs      minimum gap between compressions (default 30s). * @param summaryMaxTokens           target token count for the summary (default 100). */data class SurvivalConfig(    val maxContextTokens: Int = DEFAULT_MAX_CONTEXT_TOKENS,    val compressionThresholdPercent: Int = DEFAULT_COMPRESSION_THRESHOLD,    val compressionCooldownMs: Long = DEFAULT_COMPRESSION_COOLDOWN_MS,    val summaryMaxTokens: Int = DEFAULT_SUMMARY_MAX_TOKENS,) {    init {        require(maxContextTokens > 0) { "maxContextTokens must be positive" }        require(compressionThresholdPercent in 50..99) {            "compressionThresholdPercent must be in [50,99], got $compressionThresholdPercent"        }        require(compressionCooldownMs >= 0) { "compressionCooldownMs must be non-negative" }        require(summaryMaxTokens in 50..1000) { "summaryMaxTokens must be in [50,1000]" }    }    companion object {        /** Default context window: 4096 tokens (common for on-device LLMs). */        const val DEFAULT_MAX_CONTEXT_TOKENS = 4096        /** 85% — per strategy §5 Strategy B. */        const val DEFAULT_COMPRESSION_THRESHOLD = 85        /** 30 seconds between compressions. */        const val DEFAULT_COMPRESSION_COOLDOWN_MS = 30_000L        /** 100 tokens — per strategy §5 ("summarize in 100 tokens"). */        const val DEFAULT_SUMMARY_MAX_TOKENS = 100    }}
